import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ sources for computing and subtracting the spatial mean
sub_spatial_mean_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void compute_spatial_sum_kernel(const float* __restrict__ input,
                                           float* __restrict__ sums,
                                           int B, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = B * C * D * H * W;
    if (idx < total_size) {
        int w_i = idx % W;
        int h_i = (idx / W) % H;
        int d_i = (idx / (W * H)) % D;
        int c_i = (idx / (W * H * D)) % C;
        int b_i = (idx / (W * H * D * C)) % B;
        float val = input[idx];
        atomicAdd(&sums[b_i * C + c_i], val);
    }
}

__global__ void sub_spatial_mean_kernel(const float* __restrict__ input,
                                        const float* __restrict__ means,
                                        float* __restrict__ output,
                                        int B, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = B * C * D * H * W;
    if (idx < total_size) {
        int w_i = idx % W;
        int h_i = (idx / W) % H;
        int d_i = (idx / (W * H)) % D;
        int c_i = (idx / (W * H * D)) % C;
        int b_i = (idx / (W * H * D * C)) % B;
        float mean_val = means[b_i * C + c_i];
        output[idx] = input[idx] - mean_val;
    }
}

torch::Tensor compute_spatial_mean_cuda(torch::Tensor x) {
    // x is [B, C, D, H, W]
    auto B = x.size(0);
    auto C = x.size(1);
    auto D = x.size(2);
    auto H = x.size(3);
    auto W = x.size(4);

    auto sums = torch::zeros({B, C}, x.options());
    int total_size = B * C * D * H * W;
    int block_size = 256;
    int grid_size = (total_size + block_size - 1) / block_size;

    compute_spatial_sum_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(), sums.data_ptr<float>(), B, C, D, H, W
    );

    // Convert sums to means by dividing by (D*H*W)
    sums = sums / static_cast<float>(D * H * W);
    return sums;
}

torch::Tensor sub_spatial_mean_cuda(torch::Tensor x, torch::Tensor means) {
    // x is [B, C, D, H, W], means is [B, C]
    auto B = x.size(0);
    auto C = x.size(1);
    auto D = x.size(2);
    auto H = x.size(3);
    auto W = x.size(4);

    auto out = torch::empty_like(x);
    int total_size = B * C * D * H * W;
    int block_size = 256;
    int grid_size = (total_size + block_size - 1) / block_size;

    sub_spatial_mean_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(), means.data_ptr<float>(), out.data_ptr<float>(),
        B, C, D, H, W
    );

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("compute_spatial_mean_cuda", &compute_spatial_mean_cuda, "Compute spatial mean (CUDA)");
    m.def("sub_spatial_mean_cuda", &sub_spatial_mean_cuda, "Subtract spatial mean (CUDA)");
}
"""

sub_spatial_mean_cpp_source = r"""
torch::Tensor compute_spatial_mean_cuda(torch::Tensor x);
torch::Tensor sub_spatial_mean_cuda(torch::Tensor x, torch::Tensor means);
"""

# Load the custom CUDA extension
sub_spatial_mean_ext = load_inline(
    name="sub_spatial_mean_ext",
    cpp_sources=sub_spatial_mean_cpp_source,
    cuda_sources=sub_spatial_mean_cuda_source,
    functions=["compute_spatial_mean_cuda", "sub_spatial_mean_cuda"],
    verbose=False
)

def sub_spatial_mean(x):
    """
    Computes the mean over the spatial dimensions (D, H, W) for each [B, C]
    and subtracts it from x.
    """
    means = sub_spatial_mean_ext.compute_spatial_mean_cuda(x)
    out = sub_spatial_mean_ext.sub_spatial_mean_cuda(x, means)
    return out

class ModelNew(nn.Module):
    """
    A 3D transpose convolution layer followed by Batch Normalization, and 
    spatial mean subtraction implemented with a custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias=True):
        super().__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, 
                                                 kernel_size, stride=stride, 
                                                 padding=padding, bias=bias)
        self.batch_norm = nn.BatchNorm3d(out_channels)

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.batch_norm(x)
        x = sub_spatial_mean(x)
        return x

